import{_ as i,o as a,c as s,a6 as t}from"./chunks/framework.DL_pga9_.js";const g=JSON.parse('{"title":"NG Internals","description":"","frontmatter":{},"headers":[],"relativePath":"ref/Internals.md","filePath":"ref/Internals.md","lastUpdated":1778684593000}'),n={name:"ref/Internals.md"};function r(l,e,o,d,c,h){return a(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="ng-internals" tabindex="-1">NG Internals <a class="header-anchor" href="#ng-internals" aria-label="Permalink to “NG Internals”">​</a></h1><p>This document provides a detailed overview of the internal implementation of the NG programming language.</p><h2 id="_1-compiler-pipeline" tabindex="-1">1. Compiler Pipeline <a class="header-anchor" href="#_1-compiler-pipeline" aria-label="Permalink to “1. Compiler Pipeline”">​</a></h2><p>The NG compiler follows a traditional pipeline to process source code and execute it.</p><ol><li><strong>Lexical Analysis:</strong> The source code is scanned and converted into a stream of tokens.</li><li><strong>Parsing:</strong> The token stream is parsed to build an Abstract Syntax Tree (AST).</li><li><strong>Type Checking:</strong> The AST is traversed to perform type checking and inference.</li><li><strong>Interpretation:</strong> The AST is directly executed by the interpreter.</li></ol><h2 id="_2-lexer" tabindex="-1">2. Lexer <a class="header-anchor" href="#_2-lexer" aria-label="Permalink to “2. Lexer”">​</a></h2><p>The lexer is responsible for converting the source code into a sequence of tokens. It is implemented in <code>src/parsing/Lexer.cpp</code>.</p><p>The lexer maintains a <code>LexState</code> struct, which keeps track of the current position in the source code.</p><div class="language-cpp"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">struct</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> LexState</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Str source;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    size_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> size;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    size_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> index;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    size_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> line;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    size_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> col;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // ...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">};</span></span></code></pre></div><p>The <code>Lexer::lex()</code> method iterates through the source code and produces a <code>std::vector&lt;Token&gt;</code>.</p><h2 id="_3-parser" tabindex="-1">3. Parser <a class="header-anchor" href="#_3-parser" aria-label="Permalink to “3. Parser”">​</a></h2><p>The parser takes the token stream from the lexer and builds an AST. The parser is implemented in <code>src/parsing/ParserImpl.cpp</code>.</p><p>It uses a recursive descent parsing strategy to parse the language grammar. The <code>ParserImpl</code> class contains methods for parsing different parts of the grammar, such as <code>funDef()</code>, <code>statement()</code>, and <code>expression()</code>.</p><h2 id="_4-abstract-syntax-tree-ast" tabindex="-1">4. Abstract Syntax Tree (AST) <a class="header-anchor" href="#_4-abstract-syntax-tree-ast" aria-label="Permalink to “4. Abstract Syntax Tree (AST)”">​</a></h2><p>The AST is a tree representation of the source code. The base class for all AST nodes is <code>ASTNode</code>, defined in <code>include/ast.hpp</code>.</p><div class="language-cpp"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">struct</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ASTNode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> : NonCopyable</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    virtual</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> void</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> accept</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">AstVisitor</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">visitor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    virtual</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> auto</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> astNodeType</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ASTNodeType </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // ...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">};</span></span></code></pre></div><p>NG uses the visitor pattern to traverse the AST. The <code>AstVisitor</code> interface defines a <code>visit</code> method for each type of AST node.</p><h2 id="_5-type-checker" tabindex="-1">5. Type Checker <a class="header-anchor" href="#_5-type-checker" aria-label="Permalink to “5. Type Checker”">​</a></h2><p>The type checker traverses the AST and verifies that the program is well-typed. The type checker is implemented in <code>src/typecheck/typecheck.cpp</code>.</p><p>It uses a <code>TypeChecker</code> class, which is an <code>AstVisitor</code>, to visit each node in the AST and infer its type. The type information is stored in a <code>TypeIndex</code>, which is a map from variable names to <code>TypeInfo</code> objects.</p><h2 id="_6-interpreter" tabindex="-1">6. Interpreter <a class="header-anchor" href="#_6-interpreter" aria-label="Permalink to “6. Interpreter”">​</a></h2><p>The interpreter executes the AST directly. The main interpreter logic is in <code>src/intp/stupid.cpp</code>.</p><p>The <code>Interpreter</code> class is also an <code>AstVisitor</code>. It traverses the AST and executes the code for each node.</p><h3 id="runtime-environment" tabindex="-1">Runtime Environment <a class="header-anchor" href="#runtime-environment" aria-label="Permalink to “Runtime Environment”">​</a></h3><p>The runtime environment consists of the following components:</p><ul><li><strong><code>RuntimeSymbolTable</code> + <code>CallFrame</code>:</strong> Global definitions live in the shared symbol table, while active locals/parameters/receiver state lives in explicit <code>StorageCell</code> slots.</li><li><strong><code>NGObject</code>:</strong> A historical object-carrier name; runtime values are represented by storage cells and type/layout metadata rather than boxed object instances.</li><li><strong><code>NGType</code>:</strong> Represents runtime type metadata, including layout and cell-native protocol handlers.</li><li><strong><code>NGModule</code>:</strong> Represents module state through a module-typed storage cell with symbol slots and native state.</li></ul><h3 id="memory-management" tabindex="-1">Memory Management <a class="header-anchor" href="#memory-management" aria-label="Permalink to “Memory Management”">​</a></h3><p>NG uses <code>std::shared_ptr</code> for storage cells and managed heap references. Heap values are cloned into <code>StorageCell</code> instances and traced from symbol tables, call frames, module slots, and registered GC roots.</p><h2 id="_7-foreign-function-interface-ffi" tabindex="-1">7. Foreign Function Interface (FFI) <a class="header-anchor" href="#_7-foreign-function-interface-ffi" aria-label="Permalink to “7. Foreign Function Interface (FFI)”">​</a></h2><p>NG provides a native-function mechanism so NG declarations can be implemented in host code. On the NG side, the declaration surface remains:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fun my_native_function(arg: i32) -&gt; unit = native;</span></span></code></pre></div><h3 id="current-implementation" tabindex="-1">Current implementation <a class="header-anchor" href="#current-implementation" aria-label="Permalink to “Current implementation”">​</a></h3><p>Today, native functions are wired through the newer runtime env model:</p><ul><li>runtime/native callables use <code>NGCallable = std::function&lt;RuntimeRef&lt;StorageCell&gt;(NGSelf, NGEnv, NGArgs)&gt;</code></li><li>env-scoped runtime metadata (for example bound native module identity and slot-backed native args) flows through <code>RuntimeEnv</code></li><li>native arguments can be read through <code>NativeArgsView</code>, which can expose canonical <code>StorageCell</code> slots when available</li><li>runtime native libraries are registered through <code>register_native_library(...)</code> / <code>bind_native_library_handlers(...)</code></li><li>ORGASM VM natives are adapted through <code>wrap_native(...)</code> into the raw VM native bridge (<code>RuntimeRef&lt;StorageCell&gt;(Vec&lt;RuntimeRef&lt;StorageCell&gt;&gt;)</code>)</li><li>ORGASM bytecode-to-bytecode calls are slot-first internally (<code>execute_slots(...)</code>), so native adaptation stays on direct cell/handle semantics</li></ul><p>The remaining cleanup is no longer about <code>NGContext</code> or boxed object carriers; it is about keeping native boundaries aligned with direct cell/handle semantics.</p><h3 id="planned-direction" tabindex="-1">Planned direction <a class="header-anchor" href="#planned-direction" aria-label="Permalink to “Planned direction”">​</a></h3><p>As the runtime moves to explicit object layouts, storage cells, and call frames, native FFI should move with it.</p><p>The intended direction is:</p><ol><li><strong>Keep <code>= native</code> as the language-level declaration syntax.</strong></li><li><strong>Replace the host-side default API</strong> so native functions are registered through a shared callable descriptor and direct signature mapping instead of raw <code>NGInvocable(self, ctx, invCtx)</code> callbacks.</li><li><strong>Use the same logical ABI</strong> for interpreted functions, ORGASM functions, and native host functions: <ul><li>receiver slot</li><li>parameter slots</li><li>return slot</li><li>layout metadata for aggregates</li></ul></li><li><strong>Keep a low-level raw escape hatch</strong>, but make it an explicit advanced API rather than the default for stdlib/native bindings.</li></ol><p>In other words, the current split is:</p><ul><li><strong>done:</strong> runtime env + <code>NativeArgsView</code>, slot-backed STUPID frames, slot-backed ORGASM internal calls</li><li><strong>remaining:</strong> host/native handle wrappers and a truly shared host-facing ABI for stdlib + VM native registration</li></ul><h3 id="target-host-mapping" tabindex="-1">Target host mapping <a class="header-anchor" href="#target-host-mapping" aria-label="Permalink to “Target host mapping”">​</a></h3><p>The target FFI layer should support direct or near-1:1 mapping for the runtime categories that have stable layouts:</p><ul><li>builtin numerics and <code>bool</code></li><li><code>unit</code> / <code>void</code></li><li>string/string-view style host types</li><li><code>ref&lt;T&gt;</code> as an explicit host-side reference/cell handle</li><li>layout-backed tuple/array/object/tagged-union views or handles</li></ul><p>This is especially important for the standard library, because stdlib native functions should eventually be implemented once and reused by STUPID, ORGASM, and future native code generation without adapter shims.</p>`,45)])])}const k=i(n,[["render",r]]);export{g as __pageData,k as default};
